import java.util.*;

class Solution {
    public ListNode reverseList(ListNode head) {
        if (head == null || head.next == null) return head; // 0 or 1 node
        ListNode newHead = reverseList(head.next);          // reverse the rest
        head.next.next = head;   // old second node now points back to head
        head.next = null;        // head becomes the tail
        return newHead;
    }
}

